// Stripe closed a dispute. Say how it ended, in plain words, and what this workflow had done.
const x = ($input.first().json.data && $input.first().json.data.object) || {};

// Stripe amounts are in the smallest unit of the currency.
const ZERO = ['bif', 'clp', 'djf', 'gnf', 'jpy', 'kmf', 'krw', 'mga', 'pyg', 'rwf', 'ugx', 'vnd', 'vuv', 'xaf', 'xof', 'xpf'];
const THREE = ['bhd', 'jod', 'kwd', 'omr', 'tnd'];
const placesOf = (currency) => (ZERO.includes(currency) ? 0 : (THREE.includes(currency) ? 3 : 2));
const moneyOf = (minor, currency) => {
  const c = String(currency || '').toLowerCase();
  const p = placesOf(c);
  return (Number(minor || 0) / Math.pow(10, p)).toFixed(p) + ' ' + c.toUpperCase();
};

const OUTCOME = {
  won: 'WON. The disputed amount comes back to your Stripe balance',
  lost: 'LOST. The customer keeps the disputed amount',
  warning_closed: 'the inquiry closed without becoming a chargeback',
  prevented: 'it was prevented before it became a chargeback',
};
const marker = x.metadata && x.metadata.dispute_workflow ? String(x.metadata.dispute_workflow) : '';
const text = 'Stripe dispute ' + x.id + ' for ' + moneyOf(x.amount, x.currency) + ' is closed: ' +
  (OUTCOME[x.status] || ('status ' + x.status)) + '.' + (marker ? ' What this workflow did: ' + marker + '.' : '');
return [{ json: { text, dispute_id: x.id || null, outcome: x.status || null } }];

// Every morning: which disputes still need an answer, and how close is the deadline? Anything due
// within deadline_warning_hours goes into one Slack message. A quiet day sends nothing.
const rules = $('Dispute Rules').first().json;
const pages = $input.all().map((i) => i.json || {});
if (!pages.some((p) => Array.isArray(p.data))) {
  throw new Error('Stripe did not return a list of disputes, so no deadline was checked: ' + JSON.stringify(pages[0] || {}).slice(0, 200));
}

// Stripe amounts are in the smallest unit of the currency.
const ZERO = ['bif', 'clp', 'djf', 'gnf', 'jpy', 'kmf', 'krw', 'mga', 'pyg', 'rwf', 'ugx', 'vnd', 'vuv', 'xaf', 'xof', 'xpf'];
const THREE = ['bhd', 'jod', 'kwd', 'omr', 'tnd'];
const placesOf = (currency) => (ZERO.includes(currency) ? 0 : (THREE.includes(currency) ? 3 : 2));
const moneyOf = (minor, currency) => {
  const c = String(currency || '').toLowerCase();
  const p = placesOf(c);
  return (Number(minor || 0) / Math.pow(10, p)).toFixed(p) + ' ' + c.toUpperCase();
};

const seen = new Set();
const all = [];
for (const p of pages) for (const x of (p.data || [])) if (x && x.id && !seen.has(x.id)) { seen.add(x.id); all.push(x); }
const now = Date.now() / 1000;
const hours = Number(rules.deadline_warning_hours || 72);
const due = all.filter((x) => (x.status === 'needs_response' || x.status === 'warning_needs_response') &&
    x.evidence_details && x.evidence_details.due_by > now && x.evidence_details.due_by - now <= hours * 3600)
  .sort((a, b) => a.evidence_details.due_by - b.evidence_details.due_by);
if (!due.length) return [];
const lines = due.map((x) => {
  const e = x.evidence_details;
  const marker = x.metadata && x.metadata.dispute_workflow ? String(x.metadata.dispute_workflow) : '';
  let state = 'nothing has been saved yet';
  if ((e.submission_count || 0) > 0) state = 'an answer went in earlier, but it now needs a new one';
  else if (marker.indexOf('draft') === 0) state = 'a draft from this workflow is waiting for review';
  else if (e.has_evidence) state = 'evidence is saved but not submitted';
  return '- ' + x.id + ', ' + moneyOf(x.amount, x.currency) + ', ' + (x.status === 'warning_needs_response' ? 'inquiry' : String(x.reason || 'dispute')) +
    ': due in about ' + Math.max(0, Math.round((e.due_by - now) / 3600)) + ' hours (' + new Date(e.due_by * 1000).toISOString().slice(0, 16).replace('T', ' ') + ' UTC). ' + state + '.';
});
return [{ json: {
  text: due.length + ' Stripe dispute(s) must be answered within ' + hours + ' hours or they are lost by default:\n' + lines.join('\n') + '\nAnswer them in the Stripe Dashboard.',
  due_count: due.length, checked_count: all.length,
} }];

// Decide what to do with a new dispute from Stripe's own record of the payment. Fixed rules per
// dispute reason make the call. The model is never asked, so nothing a customer typed at checkout
// can change the verdict. Every fact the letter may use is collected here, and only here.
const rules = $('Dispute Rules').first().json;
const d = $('Read The Dispute').first().json;
const hist = $input.first().json || {};
const historyRead = Array.isArray(hist.data);
const history = historyRead ? hist.data.filter((c) => c && c.id) : [];
const ch = (d.charge && typeof d.charge === 'object') ? d.charge : {};
const pi = (d.payment_intent && typeof d.payment_intent === 'object') ? d.payment_intent : {};
const card = (ch.payment_method_details && ch.payment_method_details.card) || {};
const checks = card.checks || {};
const tds = card.three_d_secure || null;
const evd = d.evidence_details || {};
const meta = d.metadata || {};

// Stripe amounts are in the smallest unit of the currency.
const ZERO = ['bif', 'clp', 'djf', 'gnf', 'jpy', 'kmf', 'krw', 'mga', 'pyg', 'rwf', 'ugx', 'vnd', 'vuv', 'xaf', 'xof', 'xpf'];
const THREE = ['bhd', 'jod', 'kwd', 'omr', 'tnd'];
const placesOf = (currency) => (ZERO.includes(currency) ? 0 : (THREE.includes(currency) ? 3 : 2));
const moneyOf = (minor, currency) => {
  const c = String(currency || '').toLowerCase();
  const p = placesOf(c);
  return (Number(minor || 0) / Math.pow(10, p)).toFixed(p) + ' ' + c.toUpperCase();
};

const cur = String(d.currency || '').toLowerCase();
const major = (minor) => Number(minor || 0) / Math.pow(10, placesOf(cur));
const money = (minor) => moneyOf(minor, cur);
const day = (unix) => (unix ? new Date(unix * 1000).toISOString().slice(0, 10) : '');
const clean = (v) => (v === null || v === undefined ? '' : String(v).trim());
const address = (a) => (a ? [a.line1, a.line2, a.postal_code, a.city, a.state, a.country].map(clean).filter(Boolean).join(', ') : '');

const REASONS = {
  fraudulent: 'the cardholder says they did not make this payment',
  unrecognized: 'the cardholder does not recognise this payment',
  product_not_received: 'the customer says the order never arrived',
  product_unacceptable: 'the customer says the product was faulty or not as described',
  duplicate: 'the customer says they were charged twice',
  subscription_canceled: 'the customer says they were charged after cancelling',
  credit_not_processed: 'the customer says a refund they were owed never came',
  general: 'the bank gave no specific reason',
};
const reason = clean(d.reason);
const reasonText = REASONS[reason] || ('the bank gave the reason ' + reason);
const inquiry = d.status === 'warning_needs_response';
const open = d.status === 'needs_response' || inquiry;

// The facts: only what Stripe holds about this payment, or what you wrote in Dispute Rules.
const ship = ch.shipping || pi.shipping || null;
const billing = ch.billing_details || {};
const refunded = Number(ch.amount_refunded || 0);
const refunds = (ch.refunds && Array.isArray(ch.refunds.data)) ? ch.refunds.data : [];
const lastRefund = refunds.length ? refunds.reduce((a, b) => (a.created > b.created ? a : b)) : null;
const earlier = history.filter((c) => c.id !== ch.id && c.status === 'succeeded' && !c.disputed && !c.refunded && c.created < ch.created);
const fp = clean(card.fingerprint);
const sameCard = fp ? earlier.filter((c) => c.payment_method_details && c.payment_method_details.card && c.payment_method_details.card.fingerprint === fp) : [];
const capped = history.length >= 100;   // only the 100 most recent payments of the customer are read
const count = (n) => (capped ? 'at least ' : '') + n;
const customerName = clean(billing.name) || clean(ship && ship.name);
const customerEmail = clean(billing.email) || clean(ch.receipt_email) || clean(pi.receipt_email);
const bought = clean(ch.description) || clean(pi.description) || clean(rules.product_description);

const facts = [];
const fact = (label, value) => { const v = clean(value); if (v) facts.push(label + ': ' + v); };
fact('Dispute', d.id);
fact('Disputed amount', money(d.amount));
fact('Payment', ch.id);
fact('Payment date', day(ch.created));
fact('Card', (card.brand ? String(card.brand).toUpperCase() : '') + (card.last4 ? ' ending ' + card.last4 : ''));
fact('What was bought', bought);
fact('Customer name', customerName);
fact('Customer email', customerEmail);
fact('Billing address', address(billing.address));
fact('CVC check', checks.cvc_check);
fact('Street address check', checks.address_line1_check);
fact('Postal code check', checks.address_postal_code_check);
if (tds) fact('3D Secure', clean(tds.result) + (tds.version ? ' (version ' + tds.version + ')' : ''));
if (ship) {
  fact('Shipped to', address(ship.address));
  fact('Carrier', ship.carrier);
  fact('Tracking number', ship.tracking_number);
}
if (refunded > 0) fact('Refunded', money(refunded) + (lastRefund ? ' on ' + day(lastRefund.created) + ' (' + lastRefund.id + ')' : ''));
if (ch.customer && historyRead) {
  fact('Earlier paid and undisputed payments from this customer', count(earlier.length));
  if (fp) fact('Of those, made with the same card', count(sameCard.length));
}
fact('Business', rules.business_name);

// The decision. why = for your team, answer = sentences a bank may read, missing = what a person adds.
let verdict = 'fight';
let strong = false;
const why = [];
const answer = [];
const missing = [];
const minimum = Number(rules.minimum_amount_to_fight || 0);
const handled = clean(meta.dispute_workflow);
const twinWindow = 2 * 86400;
const twins = history.filter((c) => c.id !== ch.id && c.status === 'succeeded' && c.amount === ch.amount && c.currency === ch.currency && Math.abs(c.created - ch.created) <= twinWindow);
const twinOpen = twins.filter((c) => !c.refunded);
const twinRefunded = twins.filter((c) => c.refunded);
const windowCovered = !capped || history.some((c) => c.created <= ch.created - twinWindow);

if (!open) {
  verdict = 'none';
  why.push('Stripe shows this dispute as ' + clean(d.status) + ', so there is nothing to answer.');
} else if (handled) {
  verdict = 'none';
  why.push('This workflow already handled it (' + handled + '), so a repeated Stripe event changes nothing.');
} else if (refunded > 0 && refunded >= Number(d.amount || 0)) {
  strong = true;
  why.push('The payment was refunded (' + money(refunded) + ') before the dispute, so the customer would be paid twice.');
  answer.push('The customer was already refunded ' + money(refunded) + (lastRefund ? ' on ' + day(lastRefund.created) + ' (refund ' + lastRefund.id + ')' : '') + ', so the disputed amount has been returned once already.');
} else if (refunded > 0) {
  why.push('Part of the payment (' + money(refunded) + ') was already refunded. Stripe advises answering with that refund as evidence.');
  answer.push('Part of this payment, ' + money(refunded) + ', was already refunded to the customer' + (lastRefund ? ' on ' + day(lastRefund.created) : '') + '.');
  missing.push('decide whether to accept the part that was not refunded');
} else if (major(d.amount) < minimum && !inquiry) {
  verdict = 'accept';
  why.push('The disputed amount is below minimum_amount_to_fight (' + minimum + '), and countering adds a fee that Stripe returns only if you win.');
} else if (reason === 'fraudulent' || reason === 'unrecognized') {
  const shifted = !!tds && (tds.result === 'authenticated' || tds.result === 'attempt_acknowledged');
  const cvcOk = checks.cvc_check === 'pass';
  const addressOk = checks.address_line1_check === 'pass' || checks.address_postal_code_check === 'pass';
  if (shifted) {
    strong = true;
    why.push('3D Secure authenticated the payment, which moves fraud liability to the card issuer.');
    answer.push('The payment was authenticated by the cardholder with 3D Secure (result: ' + tds.result + ').');
  } else if (sameCard.length >= 2) {
    strong = true;
    why.push('The same card paid ' + count(sameCard.length) + ' earlier times without a dispute.');
    answer.push('The same card made ' + count(sameCard.length) + ' earlier payments to us that were never disputed.');
  } else if ((cvcOk && addressOk) || earlier.length >= 1) {
    why.push('There is some evidence the cardholder made the payment, but not enough on its own.');
    if (cvcOk) answer.push('The card security code (CVC) check passed.');
    if (addressOk) answer.push('The billing address check passed.');
    if (earlier.length) answer.push('This customer made ' + count(earlier.length) + ' earlier payments to us that were never disputed.');
    missing.push('add proof the cardholder used what they bought, such as a login, download or delivery record');
  } else {
    if (ch.customer && !historyRead) {
      // Missing reference data must never turn into a confident verdict: a person decides.
      missing.push('check the customer history in Stripe before deciding');
    } else {
      verdict = 'accept';
      why.push('Stripe holds no 3D Secure result, no matching address check and no earlier undisputed payment for this card, so there is little to answer a fraud claim with.');
    }
  }
} else if (reason === 'product_not_received') {
  if (ship && clean(ship.tracking_number)) {
    strong = true;
    why.push('The order was shipped with a tracking number.');
    answer.push('The order was shipped' + (address(ship.address) ? ' to ' + address(ship.address) : '') + (clean(ship.carrier) ? ' with ' + clean(ship.carrier) : '') + ', tracking number ' + clean(ship.tracking_number) + '.');
  } else {
    why.push('Stripe holds no tracking number for this payment.');
    missing.push('add proof of delivery, or proof the service was provided');
  }
} else if (reason === 'duplicate') {
  if (!ch.customer || !historyRead) {
    why.push('There is no customer history to compare this payment with.');
    missing.push('show that the payments were for separate orders');
  } else if (twinOpen.length) {
    verdict = 'accept';
    why.push('Another payment of the same amount from this customer (' + twinOpen[0].id + ' on ' + day(twinOpen[0].created) + ') was not refunded, so the claim looks right.');
  } else if (twinRefunded.length) {
    strong = true;
    why.push('The other payment of the same amount was already refunded.');
    answer.push('The other payment of the same amount, ' + twinRefunded[0].id + ', was refunded, so the customer paid only once.');
  } else if (windowCovered) {
    strong = true;
    why.push('No other payment of the same amount from this customer was made within two days.');
    answer.push('This customer made no other payment of ' + money(ch.amount) + ' within two days of this one, so it is not a duplicate.');
  } else {
    why.push('This customer has more payments than were read, so a second payment cannot be ruled out.');
    missing.push('show that the payments were for separate orders');
  }
} else if (reason === 'credit_not_processed') {
  why.push('No refund was made on this payment.');
  missing.push('explain why no refund was owed, with your refund policy');
} else if (reason === 'subscription_canceled') {
  why.push('The customer says they cancelled.');
  missing.push('add when the customer cancelled and any use after that date');
} else if (reason === 'product_unacceptable') {
  why.push('The customer says the product was not as described.');
  missing.push('add what was delivered and your refund policy');
} else {
  why.push('There is no fixed rule for this reason, so a person should look at it.');
  missing.push('add evidence that answers the reason the bank gave');
}
if (ch.customer && !historyRead) why.push('The customer history could not be read from Stripe, so it was not used.');
if (inquiry && verdict === 'accept') {
  verdict = 'fight';
  strong = false;
  why.push('This is an inquiry: accepting does not close it, so it gets a prepared answer instead.');
  missing.push('check the prepared answer');
}

let action = 'none';
if (verdict === 'accept') action = rules.accept_automatically === true ? 'accept' : 'recommend_accept';
if (verdict === 'fight') action = strong && rules.submit_automatically === true ? 'submit' : 'draft';

// The plain letter: the facts above in fixed sentences. It replaces the model's letter whenever
// that letter fails the check that follows, so there is always a letter that can be sent.
const who = clean(rules.business_name);
const opening = (who ? who + ' received' : 'We received') + ' a ' + (inquiry ? 'dispute inquiry' : 'dispute') + ' for ' + money(d.amount) + ' on payment ' + clean(ch.id) + ' of ' + day(ch.created) + '. The stated reason is that ' + reasonText + '.';
const closing = inquiry ? 'We hope this answers the inquiry.' : 'We ask that this dispute be reversed.';
const fallbackLetter = [opening, answer.length ? answer.join(' ') : 'The details of the purchase are below.', 'From our payment records:', facts.join('\n'), closing].join('\n\n');

// Evidence fields that come straight from Stripe or from your rules. Build The Stripe Evidence
// sends each one only if the dispute does not already hold a value for it.
const fields = {
  customer_name: customerName,
  customer_email_address: customerEmail,
  billing_address: address(billing.address),
  product_description: bought,
};
if (ship) {
  fields.shipping_address = address(ship.address);
  fields.shipping_carrier = clean(ship.carrier);
  fields.shipping_tracking_number = clean(ship.tracking_number);
}
if (refunded > 0 || ['credit_not_processed', 'product_unacceptable', 'general'].includes(reason)) fields.refund_policy_disclosure = clean(rules.refund_policy);
if (reason === 'subscription_canceled') fields.cancellation_policy_disclosure = clean(rules.cancellation_policy);
if (reason === 'duplicate' && strong) {
  fields.duplicate_charge_explanation = answer.join(' ');
  if (twinRefunded.length) fields.duplicate_charge_id = twinRefunded[0].id;
}

return [{ json: {
  dispute_id: clean(d.id), payment_id: clean(ch.id), stripe_status: clean(d.status), reason, reason_text: reasonText,
  inquiry, amount_text: money(d.amount),
  due_by: evd.due_by ? new Date(evd.due_by * 1000).toISOString().slice(0, 16).replace('T', ' ') + ' UTC' : '',
  verdict, strong, action, why, missing,
  facts_text: facts.join('\n'), bank_answer: answer.join(' '), fallback_letter: fallbackLetter,
  evidence_fields: fields, business_name: who,
} }];

// Accepted, or only recommended for accepting: say which in one Slack message, in plain words.

const d = $('Decide Fight Or Accept').first().json;
const got = $input.first().json || {};
const refused = got.error !== undefined && got.error !== null;
const errText = (e) => String(typeof e === 'string' ? e : (e.description || e.message || JSON.stringify(e))).slice(0, 300);
const head = 'Stripe dispute ' + d.dispute_id + ' for ' + d.amount_text + ': ' + d.reason_text + '.' +
  (d.inquiry ? ' It is an inquiry, not yet a chargeback.' : '') + ' Answer by ' + d.due_by + '.';

let body;
if (d.action === 'recommend_accept') {
  body = 'Recommendation: accept it. Nothing was sent to Stripe. ' + d.why.join(' ') + ' Accept it in the Stripe Dashboard, or turn on accept_automatically.';
} else if (refused) {
  body = 'Stripe REFUSED to accept it, so nothing changed: ' + errText(got.error) + ' Accept or answer it in the Stripe Dashboard before the deadline.';
} else {
  body = 'Accepted. Stripe now shows it as ' + got.status + '. ' + d.why.join(' ');
}
return [{ json: { text: head + '\n' + body, dispute_id: d.dispute_id, action: d.action, refused } }];

// The letter goes to a bank under your name. Every number, date, ID, email address and web link in
// it must already appear in the facts Stripe gave us, or the model's letter is replaced by the
// plain letter built from those facts. A model that did not answer is replaced the same way.
const decision = $('Decide Fight Or Accept').first().json;
const got = $input.first().json || {};
const text = typeof got.text === 'string' ? got.text.trim() : '';
const allowed = [decision.facts_text, decision.bank_answer, decision.business_name].join('\n').toLowerCase();
const numberParts = (t) => [t].concat(t.split(/[.,]/)).map((p) => p.replace(/^0+(?=\d)/, ''));
const allowedNumbers = new Set();
for (const t of (allowed.match(/\d+(?:[.,]\d+)*/g) || [])) for (const p of numberParts(t)) allowedNumbers.add(p);
const problems = [];
if (!text) {
  const e = got.error;
  problems.push(e ? 'the model did not answer (' + String(e.message || e).slice(0, 120) + ')' : 'the model returned no text');
} else {
  if (text.length > 2500) problems.push('the letter is longer than 2500 characters');
  if (/https?:\/\/|www\./i.test(text)) problems.push('the letter contains a web link');
  for (const t of (text.match(/\d+(?:[.,]\d+)*/g) || [])) {
    if (!numberParts(t).every((p) => allowedNumbers.has(p))) problems.push('the number ' + t + ' is not in the facts');
  }
  for (const id of (text.match(/\b(?:ch|py|pi|du|re|cus|pm|in|txn|evt)_[A-Za-z0-9]+/g) || [])) {
    if (!allowed.includes(id.toLowerCase())) problems.push('the ID ' + id + ' is not in the facts');
  }
  for (const em of (text.match(/[^\s@<>()]+@[^\s@<>()]+\.[A-Za-z]{2,}/g) || [])) {
    if (!allowed.includes(em.toLowerCase())) problems.push('the email address ' + em + ' is not in the facts');
  }
}
const useModel = problems.length === 0;
return [{ json: Object.assign({}, decision, {
  letter: useModel ? text : decision.fallback_letter,
  letter_source: useModel ? 'model' : 'facts_only',
  letter_problems: problems.slice(0, 5),
}) }];

// Turn the decision and the letter into the form Stripe's dispute API takes. A field that already
// holds something on the dispute - filled by Stripe from the payment, or typed by a person - is
// left alone, so this workflow can only add evidence, never replace it.
const d = $input.first().json;
const current = $('Read The Dispute').first().json.evidence || {};
const today = new Date().toISOString().slice(0, 10);
const fields = Object.assign({}, d.evidence_fields, { uncategorized_text: d.letter });
const sent = [];
const kept = [];
const parts = [];
for (const key of Object.keys(fields)) {
  const value = fields[key] === null || fields[key] === undefined ? '' : String(fields[key]).trim();
  if (!value) continue;
  const already = current[key];
  if (typeof already === 'string' && already.trim()) { kept.push(key); continue; }
  parts.push(encodeURIComponent('evidence[' + key + ']') + '=' + encodeURIComponent(value));
  sent.push(key);
}
const marker = (d.action === 'submit' ? 'submitted ' : 'draft saved ') + today;
parts.push(encodeURIComponent('metadata[dispute_workflow]') + '=' + encodeURIComponent(marker));
return [{ json: Object.assign({}, d, { body: parts.join('&'), evidence_sent: sent, evidence_kept: kept, marker }) }];

// One Slack message for the evidence that was just sent: what the rules decided, what changed in
// Stripe, and what a person still has to do before the deadline.

const d = $('Decide Fight Or Accept').first().json;
const got = $input.first().json || {};
const refused = got.error !== undefined && got.error !== null;
const errText = (e) => String(typeof e === 'string' ? e : (e.description || e.message || JSON.stringify(e))).slice(0, 300);
const head = 'Stripe dispute ' + d.dispute_id + ' for ' + d.amount_text + ': ' + d.reason_text + '.' +
  (d.inquiry ? ' It is an inquiry, not yet a chargeback.' : '') + ' Answer by ' + d.due_by + '.';

let body;
if (refused) {
  body = 'Stripe REFUSED the evidence, so nothing changed: ' + errText(got.error) + ' Answer it in the Stripe Dashboard before the deadline.';
} else if (d.action === 'submit') {
  body = 'Evidence submitted to the bank. Stripe now shows it as ' + got.status + '. ' + d.why.join(' ');
} else {
  body = 'Evidence saved as a DRAFT in Stripe. Nothing has gone to the bank yet. ' + d.why.join(' ') +
    (d.missing.length ? ' Before submitting: ' + d.missing.join('; ') + '.' : '') + ' Review and submit it in the Stripe Dashboard.';
}
const extra = [];
if (!refused) {
  const b = $('Build The Stripe Evidence').first().json;
  if (b.letter_source !== 'model') extra.push('The letter is the plain version built from Stripe facts, because ' + b.letter_problems.join('; ') + '.');
  if (b.evidence_kept.length) extra.push('Left as Stripe had them: ' + b.evidence_kept.join(', ') + '.');
}
return [{ json: { text: [head, body].concat(extra).join('\n'), dispute_id: d.dispute_id, action: d.action, refused } }];
